// HBM: a `homebrew/` file wins over a stored copy of the same brew. A brew added
// through Manage Homebrew is kept in the browser and re-pulled from the repo on
// "Update all", so it drifts from the curated local file and both load side by
// side - two of every entity under one source. Drop a stored brew only when the
// local folder already provides EVERY source it declares; it stays in storage, so
// Manage Homebrew still lists it and can delete it.
const brewsLocal = await this._pGetBrew_pGetLocalBrew({lockToken});
const localSources = new Set(brewsLocal.flatMap(brew => (brew?.body?._meta?.sources || []).map(src => src?.json).filter(Boolean)));
const brewsStored = (await this._pGetBrewRaw({lockToken}))
	.filter(brew => {
		const sources = (brew?.body?._meta?.sources || []).map(src => src?.json).filter(Boolean);
		return !sources.length || !sources.every(src => localSources.has(src));
	});
const out = [
	...brewsStored,
	...brewsLocal,
];
